<section class="admin-head"><div><p class="kicker">PIM</p><h1>Products</h1><p><?=count($items)?> structured catalogue records.</p></div><a class="btn dark" href="<?=e(url('/admin/product/new'))?>">Add product</a></section>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Status</th><th>Price</th><th>Stock mode</th><th></th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><div class="admin-product-cell"><img src="<?=e(image_url($p['image']))?>" alt=""><div><strong><?=e($p['name'])?></strong><small><?=e($p['slug'])?></small></div></div></td><td><?=e($p['sku'])?></td><td><?=e($p['category_label']??category_label($p['category']))?></td><td><span class="status-pill <?=e($p['status']??'active')?>"><?=e($p['status']??'active')?></span></td><td><?=money((int)$p['price'])?></td><td><?=!empty($p['inventory']['made_to_order'])?'Made to order':((int)($p['inventory']['stock']??0).' in stock')?></td><td><a class="text-link" href="<?=e(url('/admin/product/'.($p['guid']??'')))?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div>
